<template>
  <div class="user-avatar" :class="[sizeClass]" @click="onClick">
    <UiResponsiveImage class="user-avatar__image" mode="cover" :src="srcWithDefault" />
  </div>
</template>

<script lang="ts">
  import { Component, Emit, Prop, Vue } from 'vue-facing-decorator';
  import UiResponsiveImage from '@/app/ui-kit/UiResponsiveImage.vue';

  export type UserAvatarSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

  const DEFAULT_SRC_1 =
    'data:image/svg+xml;base64,';
  const DEFAULT_SRC_2 =
    'data:image/svg+xml;base64,';

  @Component({
    components: {
      UiResponsiveImage,
    },
  })
  export default class UserAvatar extends Vue {
    @Prop({ default: 1 }) public defaultType: number;

    @Prop() public src: string;

    @Prop() public size: UserAvatarSize;

    public get srcWithDefault() {
      return this.src === 'default' ? this.defaultSrc : this.src || this.defaultSrc;
    }

    public get sizeClass() {
      const size = this.size || 'md';
      return `user-avatar_size-${size}`;
    }

    private get defaultSrc() {
      const types = {
        2: DEFAULT_SRC_2,
        1: DEFAULT_SRC_1,
      };
      return types[this.defaultType] || types[1];
    }

    @Emit('click')
    public onClick(event: Event): Event {
      return event;
    }
  }
</script>

<style scoped lang="scss">
  .user-avatar {
    border-radius: 50%;
    flex-shrink: 0;
    overflow: hidden;
    border-width: 2px;
    border-style: solid;
    @include UiTheme() {
      background-color: UiColor(yellow-500);
    }

    &__image {
      width: 100%;
      height: 100%;
    }

    @include UiTheme() {
      border-color: UiColor(shade-100);
    }

    &_size-md {
      $size: UiGridSpacing(10);
      width: $size;
      height: $size;
    }

    &_size-sm {
      $size: UiGridSpacing(6);
      width: $size;
      height: $size;
    }

    &_size-xs {
      $size: UiGridSpacing(4);
      border-width: 1px;
      width: $size;
      height: $size;
    }

    &_size-lg {
      $size: UiGridSpacing(15);
      width: $size;
      height: $size;
    }

    &_size-xl {
      $size: UiGridSpacing(20);
      width: $size;
      height: $size;
    }
  }
</style>
